/// <summary>
/// Tính lại giá bình quân cho các mặt hàng trong lưới
/// </summary>
private bool RecalcAvgCostPrice()
{
    if (dtbData == null || dtbData.Rows.Count == 0)
    {
        return true; // không có dữ liệu thì bỏ qua, không báo lỗi
    }

    if (uStore.StoreID == null)
    {
        return true; // chưa chọn kho thì bỏ qua
    }

    // build danh sách ItemID
    string strItemID = ",";
    foreach (DataRow drw in dtbData.Rows)
    {
        if (drw["ItemID"].ToString() != "")
            strItemID += drw["ItemID"].ToString() + ",";
    }
    strItemID += ",";

    if (strItemID.Length <= 2)
    {
        return true; // không có mặt hàng thì bỏ qua
    }

    SMS_OutputVoucherDetail objDetail = new SMS_OutputVoucherDetail();
    DataTable dtbAvgCost = objDetail.GetDataTable("SMS_GetAvgCostPrice",
        "@StoreID", uStore.StoreID,
        "@ItemIDList", strItemID);

    if (dtbAvgCost == null)
    {
        return true; // lỗi thì bỏ qua, không chặn lưu
    }

    if (dtbAvgCost.Rows.Count == 0)
    {
        return true; // không có tồn kho thì bỏ qua
    }

    // tạo dictionary tra cứu
    Dictionary<string, decimal> dicAvgCost = new Dictionary<string, decimal>();
    foreach (DataRow drwAvg in dtbAvgCost.Rows)
    {
        string strItemKey = Convert.ToString(drwAvg["ItemID"]);
        decimal decAvgCost = Convert.ToDecimal(drwAvg["AvgCostPrice"]);
        if (!dicAvgCost.ContainsKey(strItemKey))
            dicAvgCost.Add(strItemKey, decAvgCost);
    }

    // cập nhật từng dòng
    foreach (DataRow drw in dtbData.Rows)
    {
        if (drw["IsDeleted"].ToString() == "0" &&
            (drw["IsSelected"].ToString() == "" || Convert.ToBoolean(drw["IsSelected"])))
        {
            string strItemKey = Convert.ToString(drw["ItemID"]);
            if (dicAvgCost.ContainsKey(strItemKey))
            {
                decimal decAvgCost = dicAvgCost[strItemKey];
                drw["CostPrice"] = decAvgCost;
                drw["OutputPrice"] = decAvgCost;
                if (dtbData.Columns.Contains("AvgCostPrice"))
                    drw["AvgCostPrice"] = decAvgCost;
                ProcessRow(drw);
            }
        }
    }

    TotalDetail();
    return true;
}

